1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .p-I { background: var(--I) !important; }
58	  .p-O { background: var(--O) !important; }
59	  .p-T { background: var(--T) !important; }
60	  .p-S { background: var(--S) !important; }
61	  .p-Z { background: var(--Z) !important; }
62	  .p-J { background: var(--J) !important; }
63	  .p-L { background: var(--L) !important; }
64	  button {
65	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
66	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
67	  }
68	  button:hover { border-color: var(--muted); }
69	  .keys { color: var(--muted); font-size: 13px; }
70	</style>
71	</head>
72	<body>
73	<div class="game">
74	  <div class="board" data-testid="board" id="board"></div>
75	  <div class="side">
76	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
77	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
78	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
79	    <div class="box"><div class="label">Next</div><div class="preview" id="preview"></div></div>
80	    <button id="restart" type="button">New game</button>
81	    <div class="keys">← → move<br>↓ soft drop<br>Space hard drop</div>
82	  </div>
83	</div>
84	<script>
85	(function () {
86	  "use strict";
87	
88	  var ROWS = 20, COLS = 10;
89	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
90	
91	  // Spawn shapes as [row, col] offsets from the piece origin.
92	  var SHAPES = {
93	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
94	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
95	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
96	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
97	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
98	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
99	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
100	  };
101	  var SPAWN_COL = 3;
102	  var GRAVITY_MS = 1000;
103	
104	  var state = {
105	    board: [],      // ROWS x COLS, "" or piece letter
106	    current: null,  // { type, row, col }
107	    next: [],
108	    score: 0,
109	    level: 1,
110	    lines: 0,
111	    status: "running"
112	  };
113	
114	  // ---- core logic ----
115	
116	  function emptyBoard() {
117	    var b = [];
118	    for (var r = 0; r < ROWS; r++) {
119	      var row = [];
120	      for (var c = 0; c < COLS; c++) row.push("");
121	      b.push(row);
122	    }
123	    return b;
124	  }
125	
126	  function randomType() {
127	    return TYPES[Math.floor(Math.random() * TYPES.length)];
128	  }
129	
130	  function cellsOf(piece, dRow, dCol) {
131	    return SHAPES[piece.type].map(function (o) {
132	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
133	    });
134	  }
135	
136	  function fits(piece, dRow, dCol) {
137	    return cellsOf(piece, dRow, dCol).every(function (p) {
138	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
139	    });
140	  }
141	
142	  function spawn() {
143	    var type = state.next.length ? state.next.shift() : randomType();
144	    if (!state.next.length) state.next.push(randomType());
145	    state.current = { type: type, row: 0, col: SPAWN_COL };
146	  }
147	
148	  function lock() {
149	    var piece = state.current;
150	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
151	    state.current = null;
152	    spawn();
153	  }
154	
155	  function tryMove(dRow, dCol) {
156	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
157	    state.current.row += dRow;
158	    state.current.col += dCol;
159	    return true;
160	  }
161	
162	  // One gravity step. The timer and __tetris.tick both call this.
163	  function gravityStep() {
164	    if (state.status !== "running" || !state.current) return;
165	    if (!tryMove(1, 0)) lock();
166	  }
167	
168	  var actions = {
169	    left: function () { tryMove(0, -1); },
170	    right: function () { tryMove(0, 1); },
171	    softDrop: function () { tryMove(1, 0); },
172	    hardDrop: function () {
173	      if (!state.current) return;
174	      while (tryMove(1, 0)) {}
175	      lock();
176	    }
177	  };
178	
179	  function doAction(name) {
180	    if (state.status !== "running" || !actions[name]) return;
181	    actions[name]();
182	    render();
183	  }
184	
185	  function newGame(queue) {
186	    state.board = emptyBoard();
187	    state.score = 0;
188	    state.level = 1;
189	    state.lines = 0;
190	    state.status = "running";
191	    state.next = Array.isArray(queue) ? queue.slice() : [];
192	    spawn();
193	    restartTimer();
194	    render();
195	  }
196	
197	  // ---- rendering (synchronous) ----
198	
199	  var boardEl = document.getElementById("board");
200	  var previewEl = document.getElementById("preview");
201	  var scoreEl = document.getElementById("score");
202	  var levelEl = document.getElementById("level");
203	  var linesEl = document.getElementById("lines");
204	  var cellEls = [];
205	  var previewEls = [];
206	
207	  (function buildDom() {
208	    for (var r = 0; r < ROWS; r++) {
209	      var row = [];
210	      for (var c = 0; c < COLS; c++) {
211	        var el = document.createElement("div");
212	        el.className = "cell";
213	        el.setAttribute("data-testid", "cell");
214	        el.setAttribute("data-row", String(r));
215	        el.setAttribute("data-col", String(c));
216	        el.setAttribute("data-filled", "false");
217	        el.setAttribute("data-piece", "");
218	        boardEl.appendChild(el);
219	        row.push(el);
220	      }
221	      cellEls.push(row);
222	    }
223	    for (var i = 0; i < 8; i++) {
224	      var p = document.createElement("div");
225	      previewEl.appendChild(p);
226	      previewEls.push(p);
227	    }
228	  })();
229	
230	  function paint(el, type) {
231	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
232	  }
233	
234	  function render() {
235	    var view = state.board.map(function (row) { return row.slice(); });
236	    if (state.current) {
237	      cellsOf(state.current).forEach(function (p) {
238	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
239	      });
240	    }
241	    for (var r = 0; r < ROWS; r++) {
242	      for (var c = 0; c < COLS; c++) {
243	        var el = cellEls[r][c], t = view[r][c];
244	        el.setAttribute("data-filled", t ? "true" : "false");
245	        el.setAttribute("data-piece", t);
246	        paint(el, t);
247	      }
248	    }
249	    previewEls.forEach(function (el) { paint(el, ""); });
250	    var nextType = state.next[0];
251	    if (nextType) {
252	      SHAPES[nextType].forEach(function (o) { paint(previewEls[o[0] * 4 + o[1]], nextType); });
253	    }
254	    scoreEl.textContent = String(state.score);
255	    levelEl.textContent = String(state.level);
256	    linesEl.textContent = String(state.lines);
257	  }
258	
259	  // ---- timer ----
260	
261	  var timer = null;
262	  function onTimer() { gravityStep(); render(); }
263	  function restartTimer() {
264	    if (timer) clearInterval(timer);
265	    timer = setInterval(onTimer, GRAVITY_MS);
266	  }
267	
268	  // ---- input ----
269	
270	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", " ": "hardDrop" };
271	  document.addEventListener("keydown", function (e) {
272	    var action = KEYS[e.key];
273	    if (!action) return;
274	    e.preventDefault();
275	    doAction(action);
276	  });
277	  document.getElementById("restart").addEventListener("click", function (e) {
278	    e.currentTarget.blur();
279	    newGame();
280	  });
281	
282	  // ---- test control surface ----
283	
284	  window.__tetris = {
285	    newGame: function (queue) { newGame(queue); },
286	    setQueue: function (queue) {
287	      state.next = Array.isArray(queue) ? queue.slice() : [];
288	      render();
289	    },
290	    setBoard: function (rows) {
291	      state.board = rows.map(function (line) {
292	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
293	      });
294	      render();
295	    },
296	    tick: function (n) {
297	      var steps = n === undefined ? 1 : n;
298	      for (var i = 0; i < steps; i++) gravityStep();
299	      render();
300	    },
301	    input: function (action) { doAction(action); },
302	    getBoard: function () {
303	      return state.board.map(function (row) {
304	        return row.map(function (t) { return t || "."; }).join("");
305	      });
306	    },
307	    getState: function () {
308	      return {
309	        current: state.current
310	          ? { type: state.current.type, cells: cellsOf(state.current) }
311	          : null,
312	        next: state.next.slice(),
313	        score: state.score,
314	        level: state.level,
315	        lines: state.lines,
316	        status: state.status
317	      };
318	    }
319	  };
320	
321	  newGame();
322	})();
323	</script>
324	</body>
325	</html>
